COLS = ['datetime','open','high','low','close','volume','oi']

for stock, candles in DATA.items():
    pq_path = DS3_DIR / f'{stock}.parquet'
    df_ds3  = pd.read_parquet(pq_path)

    # Normalise existing datetimes
    if df_ds3['datetime'].dt.tz is None:
        df_ds3['datetime'] = df_ds3['datetime'].dt.tz_localize(IST)
    else:
        df_ds3['datetime'] = df_ds3['datetime'].dt.tz_convert(IST)

    # Parse new candles
    rows = []
    for c in candles:
        dt = pd.to_datetime(c['date']).astimezone(IST)
        rows.append({
            'datetime': dt,
            'open':   float(c['open']),
            'high':   float(c['high']),
            'low':    float(c['low']),
            'close':  float(c['close']),
            'volume': int(c['volume']),
            'oi':     int(c.get('oi', 0)),
        })

    df_new_day = pd.DataFrame(rows)
    df_new_day['datetime'] = pd.to_datetime(df_new_day['datetime']).dt.tz_convert(IST)

    df_out = pd.concat([df_ds3[COLS], df_new_day[COLS]], ignore_index=True)
    df_out = (df_out
              .sort_values('datetime')
              .drop_duplicates(subset='datetime')
              .reset_index(drop=True))

    df_out.to_parquet(pq_path, index=False)
    trading_days = df_out['datetime'].dt.date.nunique()
    print(f'  OK  {stock}: +{len(rows)} Dec-31 candles (Kite) | '
          f'total {len(df_out):,} candles | {trading_days} trading days')

print('\nDone.')
